mapper.select:
SELECT o.id, o.order_no, o.product_id, o.buyer_id, o.seller_id, o.amount, o.status, o.delivery_type, o.remark, o.cancel_reason, o.refund_reason, o.refund_reject_reason, o.pay_time, o.deliver_time, o.receive_time, o.cancel_time, o.create_time, p.title AS product_title, p.cover_color AS product_cover_color, b.nickname AS buyer_nickname, b.avatar_color AS buyer_avatar_color, s.nickname AS seller_nickname, s.avatar_color AS seller_avatar_color, (SELECT COUNT(*) FROM tb_review rv WHERE rv.order_id = o.id) > 0 AS reviewed FROM tb_order o LEFT JOIN tb_product p ON o.product_id = p.id LEFT JOIN tb_user b ON o.buyer_id = b.id LEFT JOIN tb_user s ON o.seller_id = s.id
AND o.buyer_id = #{buyerId} AND o.seller_id = #{sellerId} AND o.status = #{status}
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR p.title LIKE CONCAT('%', #{keyword}, '%'))
AND o.create_time >= #{beginTime} AND o.create_time <= #{endTime}
ORDER BY o.create_time DESC, o.id DESC
